<script>
(()=>{const form=document.getElementById('promotion-editor');if(!form)return;const type=form.elements.DiscountType;const value=form.elements.Value;const starts=form.elements.StartsAt;const ends=form.elements.EndsAt;const update=()=>{value.max=type.value==='Percent'?'100':'';value.setCustomValidity(type.value==='Percent'&&Number(value.value)>100?'Percentage discounts cannot exceed 100.':'');};type.addEventListener('change',update);value.addEventListener('input',update);form.addEventListener('submit',event=>{update();if(starts.value&&ends.value&&new Date(ends.value)<=new Date(starts.value)){event.preventDefault();ends.setCustomValidity('End date must be after start date.');ends.reportValidity();return;}ends.setCustomValidity('');if(!form.reportValidity())event.preventDefault();});ends.addEventListener('input',()=>ends.setCustomValidity(''));})();
</script>
